enum light_method_t
{
  LIGHT_METHOD_DIFFUSE = 0,
  LIGHT_METHOD_ADDITIVE_DYNAMIC_ONLY = 1
};

class material
{
public:
  unsigned int get_flags() const __asm__("get_flags__C8material");
  void set_flags(unsigned int) __asm__("set_flags__8materialUi");
  void process_vertex_contexts() __asm__("process_vertex_contexts__8material");
};

template<class T> class vector
{
  T* start;
  T* finish;
  T* end_of_storage;
public:
  unsigned int size() const { return finish - start; }
  T& operator[](unsigned int n) { return start[n]; }
};

class vr_pmesh
{
  char pad[0x38];
  vector<material*> materials;
  char pad2[0x5c];
  unsigned mesh_flags;
public:
  enum { NORMAL=0, FORCE_LIGHT=1 };
  void set_light_method(light_method_t lmt);
};

void vr_pmesh::set_light_method( light_method_t lmt )
{
  if(lmt==LIGHT_METHOD_DIFFUSE)
  {
    mesh_flags = (mesh_flags & ~1) | FORCE_LIGHT;
  }
  else
  {
    mesh_flags = (mesh_flags & ~1) | NORMAL;
  }
  for( int i=0 ; i<(int)materials.size() ; ++i )
  {
    if(lmt==LIGHT_METHOD_DIFFUSE)
      materials[i]->set_flags( materials[i]->get_flags() & (0xffff^0x08) );
    else
      materials[i]->set_flags( materials[i]->get_flags()| 0x08 );

    materials[i]->process_vertex_contexts();
  }
}
